//! DEEP V1: the cross-language vectors (fixtures/deepswap-v1-vectors.json, generated by
//! packages/curve-math) against the on-chain math in `curve/v1.rs` and `PoolState::v1_rates`.
//! New file, not in upstream. The same file is consumed by the TypeScript tests and by the
//! Jupiter adapter, so all three implementations agree to the unit.

use deep_amm::curve::v1::{
    swap_base_input_v1, swap_base_output_v1, MAX_REWARD_RATE, MAX_TOTAL_FEE_RATE,
};
use deep_amm::curve::FEE_RATE_DENOMINATOR_VALUE;
use deep_amm::states::{AmmConfig, CreatorFeeOn, PoolState, FEE_MODEL_V1};
use serde_json::Value;

const VECTORS: &str = include_str!("../../../fixtures/deepswap-v1-vectors.json");

fn n(v: &Value) -> u128 {
    v.as_str()
        .unwrap_or_else(|| panic!("expected a decimal string, got {v}"))
        .parse()
        .unwrap()
}

fn rate(v: &Value) -> u64 {
    // rates in "ok": false vectors may be anything up to u64::MAX
    u64::try_from(n(v)).unwrap()
}

fn vectors() -> Value {
    serde_json::from_str(VECTORS).unwrap()
}

#[test]
fn fixture_constants_match_the_program() {
    let v = vectors();
    assert_eq!(
        n(&v["feeRateDenominator"]),
        u128::from(FEE_RATE_DENOMINATOR_VALUE)
    );
    assert_eq!(n(&v["maxTotalFeeRate"]), u128::from(MAX_TOTAL_FEE_RATE));
    assert_eq!(n(&v["maxRewardRate"]), u128::from(MAX_REWARD_RATE));
    assert_eq!(MAX_TOTAL_FEE_RATE, deep_amm::deep_keys::MAX_TOTAL_FEE_RATE);
    assert_eq!(MAX_REWARD_RATE, deep_amm::deep_keys::MAX_REWARD_RATE);
    // the owner's V1 schedule is a valid config
    let s = &v["schedule"];
    let cfg = AmmConfig {
        fee_model: FEE_MODEL_V1,
        buy_lp_fee_rate: rate(&s["buyLpFeeRate"]),
        buy_protocol_fee_rate: rate(&s["buyProtocolFeeRate"]),
        sell_lp_fee_rate: rate(&s["sellLpFeeRate"]),
        sell_protocol_fee_rate: rate(&s["sellProtocolFeeRate"]),
        ..Default::default()
    };
    assert!(cfg.validate_v1_rates().is_ok());
    assert_eq!(
        (
            cfg.buy_lp_fee_rate,
            cfg.buy_protocol_fee_rate,
            cfg.sell_lp_fee_rate,
            cfg.sell_protocol_fee_rate,
        ),
        (1_000, 2_500, 1_000, 6_500)
    );
}

/// Checks one result against a vector, including the real reserves after the swap (the LP
/// part stays in; the DEEP and reward parts leave the quote side).
fn check(
    c: &Value,
    name: &str,
    is_buy: bool,
    r: Option<deep_amm::curve::SwapResult>,
    reserve_in: u128,
    reserve_out: u128,
) {
    if !c["ok"].as_bool().unwrap() {
        assert!(r.is_none(), "{name}: must be rejected");
        return;
    }
    let r = r.unwrap_or_else(|| panic!("{name}: must succeed"));
    let lp = r.trade_fee - r.protocol_fee;
    assert_eq!(r.input_amount, n(&c["amountIn"]), "{name}: amountIn");
    assert_eq!(r.output_amount, n(&c["amountOut"]), "{name}: amountOut");
    assert_eq!(lp, n(&c["lpFee"]), "{name}: lpFee");
    assert_eq!(r.protocol_fee, n(&c["protocolFee"]), "{name}: protocolFee");
    assert_eq!(r.creator_fee, n(&c["rewardFee"]), "{name}: rewardFee");
    assert_eq!(r.fund_fee, 0, "{name}: no fund fee");
    assert_eq!(
        lp + r.protocol_fee + r.creator_fee,
        n(&c["totalFee"]),
        "{name}: parts sum to the total"
    );
    assert_eq!(
        r.new_input_vault_amount,
        n(&c["newInputVault"]),
        "{name}: newInputVault"
    );
    assert_eq!(
        r.new_output_vault_amount,
        n(&c["newOutputVault"]),
        "{name}: newOutputVault"
    );
    let taken = r.protocol_fee + r.creator_fee;
    let (after_in, after_out) = if is_buy {
        (
            reserve_in + r.input_amount - taken,
            reserve_out - r.output_amount,
        )
    } else {
        (
            reserve_in + r.input_amount,
            reserve_out - r.output_amount - taken,
        )
    };
    assert_eq!(after_in, n(&c["reserveInAfter"]), "{name}: reserveInAfter");
    assert_eq!(
        after_out,
        n(&c["reserveOutAfter"]),
        "{name}: reserveOutAfter"
    );
    // the invariant the handler enforces
    if let Some(k) = r
        .new_input_vault_amount
        .checked_mul(r.new_output_vault_amount)
    {
        assert!(k >= reserve_in * reserve_out, "{name}: k decreased");
    }
}

#[test]
fn exact_in_vectors() {
    let v = vectors();
    let cases = v["exactIn"].as_array().unwrap();
    assert!(cases.len() >= 60, "too few exactIn vectors");
    let (mut ok, mut rejected) = (0, 0);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let is_buy = c["isBuy"].as_bool().unwrap();
        let (x, y) = (n(&c["reserveIn"]), n(&c["reserveOut"]));
        let r = swap_base_input_v1(
            n(&c["amountIn"]),
            x,
            y,
            rate(&c["lpRate"]),
            rate(&c["protocolRate"]),
            rate(&c["rewardRate"]),
            is_buy,
        );
        if r.is_some() {
            ok += 1
        } else {
            rejected += 1
        }
        check(c, name, is_buy, r, x, y);
    }
    assert!(ok >= 40 && rejected >= 1, "{ok} ok, {rejected} rejected");
}

#[test]
fn exact_out_vectors() {
    let v = vectors();
    let cases = v["exactOut"].as_array().unwrap();
    assert!(cases.len() >= 40, "too few exactOut vectors");
    let (mut ok, mut rejected) = (0, 0);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let is_buy = c["isBuy"].as_bool().unwrap();
        let (x, y) = (n(&c["reserveIn"]), n(&c["reserveOut"]));
        let r = swap_base_output_v1(
            n(&c["amountOut"]),
            x,
            y,
            rate(&c["lpRate"]),
            rate(&c["protocolRate"]),
            rate(&c["rewardRate"]),
            is_buy,
        );
        if r.is_some() {
            ok += 1
        } else {
            rejected += 1
        }
        check(c, name, is_buy, r, x, y);
    }
    assert!(ok >= 25 && rejected >= 1, "{ok} ok, {rejected} rejected");
}

/// `PoolState::v1_rates`: the config's LP and DEEP rates of the side (capped together) and
/// the pool's own reward rate (capped on its own).
#[test]
fn pool_rates_vectors() {
    let v = vectors();
    let cases = v["poolRates"].as_array().unwrap();
    assert!(cases.len() >= 12, "too few poolRates vectors");
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let cfg = AmmConfig {
            fee_model: FEE_MODEL_V1,
            buy_lp_fee_rate: rate(&c["buyLpFeeRate"]),
            buy_protocol_fee_rate: rate(&c["buyProtocolFeeRate"]),
            sell_lp_fee_rate: rate(&c["sellLpFeeRate"]),
            sell_protocol_fee_rate: rate(&c["sellProtocolFeeRate"]),
            ..Default::default()
        };
        // the raw fields are written directly, to also cover states `set_v1` refuses to
        // store (a rate on a Standard pool, a rate above the cap)
        let mut pool = PoolState::default();
        pool.set_v1(CreatorFeeOn::OnlyToken0, 0, 0).unwrap();
        pool.reward_model = u8::try_from(c["rewardModel"].as_u64().unwrap()).unwrap();
        pool.reward_rate_snapshot = rate(&c["rewardRateSnapshot"]);
        let got = pool.v1_rates(&cfg, c["isBuy"].as_bool().unwrap());
        if !c["ok"].as_bool().unwrap() {
            assert!(got.is_err(), "{name}: must be rejected");
            continue;
        }
        let got = got.unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert_eq!(
            (got.lp, got.protocol, got.reward),
            (
                rate(&c["lpRate"]),
                rate(&c["protocolRate"]),
                rate(&c["rewardRate"])
            ),
            "{name}"
        );
        assert!(got.total() <= MAX_TOTAL_FEE_RATE, "{name}: above the cap");
        assert!(
            got.reward <= MAX_REWARD_RATE,
            "{name}: reward above its ceiling"
        );
    }
}
